import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"EmakiStructure","description":"","frontmatter":{},"headers":[],"relativePath":"modules/structure/index.md","filePath":"modules/structure/index.md","lastUpdated":0}`),a={name:`modules/structure/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="emakistructure" tabindex="-1">EmakiStructure <a class="header-anchor" href="#emakistructure" aria-label="Permalink to “EmakiStructure”">​</a></h1><p>EmakiStructure 帮你做两件事: <strong>结构生成</strong> 与 <strong>多方块结构交互</strong></p><ul><li>先用命令框选一块区域, 把它导出成结构模板 (<code>.nbt</code> 文件), 之后随时按指定朝向重新放到别处</li><li>你可以把&quot;用方块摆出来的机关&quot;记录成多方块定义, 玩家摆好形状后, 插件自动执行你配置的动作</li><li>生成中途如果被 reload 或停服打断, 插件会把地皮还原成生成前的样子</li><li>你可以在<strong>尚未生成的区块</strong>里, 把原版结构 (例如村庄) 换成你自己的模板</li><li>导出时插件会自动识别 ItemsAdder / Oraxen / Nexo / CraftEngine 放置的家具, 放置时按原样摆回去</li></ul><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to “基本信息”">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>模块版本</td><td><code>1.0.8</code></td></tr><tr><td>构建产物</td><td><code>EmakiStructure-1.0.8.jar</code></td></tr><tr><td>API 坐标</td><td><code>emaki.jiuwu.craft:emaki-structure-api:1.0.2</code> (只给开发者编译用, 不要放进 <code>plugins/</code>)</td></tr><tr><td>主命令</td><td><code>/emakistructure</code> (别名 <code>/ems</code>, <code>/estruct</code>)</td></tr><tr><td>必需依赖</td><td>EmakiCoreLib (<code>required: true</code>)</td></tr><tr><td>可选依赖</td><td>MythicMobs, EmakiMobs, ItemsAdder, Oraxen, Nexo, CraftEngine (都不装也能用, 只是对应功能会停用)</td></tr><tr><td>权限节点</td><td><code>emakistructure.use</code>, <code>emakistructure.edit</code>, <code>emakistructure.reload</code>, <code>emakistructure.admin</code></td></tr><tr><td>支持的平台</td><td>Paper 26.1, 支持 Folia (<code>folia-supported: true</code>)</td></tr></tbody></table><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>EmakiStructure 属于 <code>.key</code> 门控的私有模块: 只有源码仓库根目录存在 <code>.key</code> 文件时, 它才会参与默认构建. 如果你只是安装使用, 忽略这一条就行</p></div><h2 id="功能页面" tabindex="-1">功能页面 <a class="header-anchor" href="#功能页面" aria-label="Permalink to “功能页面”">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td><a href="./commands.html">命令与权限</a></td><td>框选, 导出, 放置, 多方块与调试命令</td></tr><tr><td><a href="./templates.html">结构模板</a></td><td>选区高亮, <code>.nbt</code> 导入导出校验, 生物点位与家具附属配置</td></tr><tr><td><a href="./multiblocks.html">多方块结构</a></td><td><code>multiblocks/*.yml</code> 定义, 触发与增量检测</td></tr><tr><td><a href="./configuration.html">配置详解</a></td><td><code>config.yml</code> 全部配置键说明</td></tr><tr><td><a href="./api.html">API 与集成</a></td><td>给开发者: <code>emaki-structure-api</code> 门面与 <code>MultiblockTriggerEvent</code></td></tr></tbody></table><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to “核心能力”">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>两点框选</td><td>用 <code>/ems select pos1</code> / <code>pos2</code> 记下两个角点, <code>adjust</code> 微调大小, <code>clear</code> 取消; 框好的区域会用发光线框画在你眼前</td></tr><tr><td>结构模板</td><td>把选区导出成 <code>structures/&lt;名称&gt;.nbt</code>, 之后按朝向 (含左右镜像) 重新放置; 导入时会逐项检查体积, 颜色表, 方块自带数据的大小</td></tr><tr><td>生成时的保护</td><td>限制每 1/20 秒最多写多少方块, 服务器卡顿时自动降速, 排队超时自动中止, 支撑面不足时按策略处理 (<code>skip</code>/<code>keep</code>/<code>fill</code>), 以及防止玩家被生成的结构埋住</td></tr><tr><td>生成回滚</td><td>生成被 reload / 停服 / 超时 / 超限打断时, 只把被改动过的方块记进日志, 并据此还原到生成前的样子; 重启后会清理没提交完的记录</td></tr><tr><td>替换原版结构</td><td>对<strong>尚未生成的区块</strong>, 按 <code>replace_rules</code> 把原版结构 (如村庄) 换成你准备的模板; 已经生成的区块永远不会被改写</td></tr><tr><td>多方块结构</td><td>按选区导出 <code>multiblocks/&lt;id&gt;.yml</code>, 玩家摆好形状并交互时执行配置的动作; 支持形状校验, 冷却, 触发条件与增量检测</td></tr><tr><td>家具四源</td><td>导出时识别 ItemsAdder / Oraxen / Nexo / CraftEngine 的家具并记入 <code>furniture/&lt;模板&gt;.yml</code>, 放置时按朝向摆回, 回滚时移除</td></tr><tr><td>结构内生物</td><td><code>spawns/&lt;模板&gt;.yml</code> 里写好生物点位后, 结构生成时按点位 / 球形范围 / 区域范围生成生物 (支持 <code>minecraft:</code> / <code>mythicmobs:</code> / <code>emakimobs:</code> 前缀)</td></tr></tbody></table><h2 id="默认配置目录" tabindex="-1">默认配置目录 <a class="header-anchor" href="#默认配置目录" aria-label="Permalink to “默认配置目录”">​</a></h2><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiStructure/</span></span>
<span class="line"><span>├── config.yml</span></span>
<span class="line"><span>├── structures/           ← .nbt 结构模板 (由 structure export 生成)</span></span>
<span class="line"><span>├── multiblocks/          ← 多方块定义 (由 multiblock export 生成)</span></span>
<span class="line"><span>├── spawns/               ← 结构内生物点位 (手写)</span></span>
<span class="line"><span>├── furniture/            ← 家具记录 (导出结构时自动生成)</span></span>
<span class="line"><span>├── journal/              ← 生成回滚日志 (运行时自动生成)</span></span>
<span class="line"><span>├── replaced/             ← 已替换过的原版结构记录 (运行时自动生成)</span></span>
<span class="line"><span>└── lang/</span></span></code></pre></div><p><code>structures/</code> 与 <code>multiblocks/</code> 通常由游戏内命令导出生成, 你也可以手工放进去; <code>spawns/</code> 与 <code>furniture/</code> 需要手写或由导出产生; <code>journal/</code> 与 <code>replaced/</code> 是插件运行时自动生成的, <strong>不要手工编辑</strong>. 手工改过 <code>spawns/</code> 等文件后, 执行一次 <code>/ems reload</code> 才会生效</p><h2 id="典型工作流" tabindex="-1">典型工作流 <a class="header-anchor" href="#典型工作流" aria-label="Permalink to “典型工作流”">​</a></h2><ol><li>先 <code>/ems select pos1</code> 与 <code>/ems select pos2</code> 框选一块区域, 记下回显的尺寸</li><li>再用 <code>/ems structure export &lt;名称&gt;</code> 把它导出成 <code>structures/&lt;名称&gt;.nbt</code></li><li>(可选) 手写 <code>spawns/&lt;名称&gt;.yml</code> 指定这个结构里要生成什么生物; 如果选区里有家具插件的方块, 家具记录会在导出时自动一起生成</li><li>用 <code>/ems get &lt;名称&gt; [朝向]</code> 就地预览效果, 满意后执行 <code>/ems structure place &lt;名称&gt; &lt;朝向&gt;</code> 正式放置</li><li>多方块: 执行 <code>/ems multiblock export &lt;id&gt;</code> 按选区记录机关布局, 玩家摆好形状后自动触发动作</li><li>想让某些原版结构被替换掉时, 在 <code>config.yml</code> 的 <code>replace_rules</code> 里加规则</li></ol><h2 id="与其他模块的关系" tabindex="-1">与其他模块的关系 <a class="header-anchor" href="#与其他模块的关系" aria-label="Permalink to “与其他模块的关系”">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>协作方式</th></tr></thead><tbody><tr><td>EmakiCoreLib</td><td>必需依赖: 提供定时任务调度, 调试命令, 消息与配置检查; 多方块的触发动作由 CoreLib 执行</td></tr><tr><td>EmakiMobs / MythicMobs</td><td>装了之后, <code>spawns/</code> 里可以写 <code>emakimobs:</code> / <code>mythicmobs:</code> 开头的自定义生物 (两者都可不装)</td></tr><tr><td>ItemsAdder / Oraxen / Nexo / CraftEngine</td><td>家具与自定义方块的来源. 没装对应插件时, 相关家具条目会被跳过并在控制台提示</td></tr></tbody></table>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};